def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    background = 9

    # Create output grid
    output = [[background] * cols for _ in range(rows)]

    # Find the template - a connected component of non-background values
    # For this task, template appears at rows 8-10, cols 3, 9, 15, 18 (positions with 8)
    # But actually templates are blocks like the ones in demo 1

    # Find large clusters of connected non-9 values
    from collections import deque

    visited = set()
    templates = []
    markers = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and (r, c) not in visited:
                # BFS to find connected component
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != background and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                if len(component) >= 3:
                    templates.append(component)
                else:
                    markers.append((r, c))

    # Apply templates to marker positions
    for comp in templates:
        for marker_r, marker_c in markers:
            for tr, tc in comp:
                if 0 <= marker_r + tr < rows and 0 <= marker_c + tc < cols:
                    output[marker_r + tr][marker_c + tc] = grid[tr][tc]

    # Copy markers and templates
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                output[r][c] = grid[r][c]

    return output
